package com.aicharacter.v3;
/** Executes only validated present/future world conditions. Never writes girl cognition, relationship, memory or past history. */
public final class GodWorldEventExecutor{private GodWorldEventExecutor(){}
 public static Result apply(WorldState s,GodWorldEventProposal p,long now){GodWorldEventProposal.Result v=GodWorldEventProposal.validate(s,p,now);if(!v.ok)return new Result(false,v.reason,null);if(p.requestedAt>now)return new Result(false,"future scheduling is not enabled yet",null);String weather="WEATHER_RAIN".equals(p.type)?"RAIN":"WEATHER_CLOUDY".equals(p.type)?"CLOUDY":"CLEAR";if(weather.equals(s.environment.weather))return new Result(false,"world condition already active",null);s.environment.setWeather(weather,p.intensity,now);String id="god_world_"+p.id+"_"+Long.toHexString(now);WorldHistoryEntry e=WorldEventBus.publishId(s,now,id,"GOD_WORLD_CONDITION","environment","A world condition began: "+weather+".");return new Result(true,"world condition began",e);}
 public static final class Result{public final boolean ok;public final String message;public final WorldHistoryEntry event;Result(boolean ok,String message,WorldHistoryEntry event){this.ok=ok;this.message=message;this.event=event;}}
}